205	void
206	set_fs(int fs)
207	{
208	  if (fs != 48 && fs != 96 && fs != 192)
209	    return;
210	
211	  if (fs != current_fs) {
212	    current_fs = fs;
213	    // stop WCLK,BCLK
214	    tlv320aic3204_stop();
215	
216	    // then stop I2S
217	    i2sStopExchange(&I2SD2);
218	    // wait a second (not enough in 20ms)
219	    chThdSleepMilliseconds(40);
220	    // re-prepare I2S
221	    i2sStartExchange(&I2SD2);
222	
223	    // enable WCLK,BCLK
224	    tlv320aic3204_set_fs(fs);
225	  }
226	}
