258	void i2s_end_callback(I2SDriver *i2sp, size_t offset, size_t n)
259	{
260	  int32_t cnt_s = port_rt_get_counter_value();
261	  int32_t cnt_e;
262	  int16_t *p = &rx_buffer[offset];
263	  int16_t *q = &tx_buffer[offset];
264	  (void)i2sp;
265	  palSetPad(GPIOC, GPIOC_LED);
266	
267	  (*signal_process)(p, q, n);
268	
269	  cnt_e = port_rt_get_counter_value();
270	  stat.interval_cycles = cnt_s - stat.last_counter_value;
271	  stat.busy_cycles = cnt_e - cnt_s;
272	  stat.last_counter_value = cnt_s;
273	
274	  stat.callback_count++;
275	  palClearPad(GPIOC, GPIOC_LED);
276	}
