395	uint16_t adc_single_read(ADC_TypeDef *adc, uint32_t chsel)
396	{
397	  /* ADC setup */
398	  adc->ISR    = adc->ISR;
399	  adc->IER    = 0;
400	  adc->SMPR1  = ADC_SMPR1_SMP0_2; // 19.5 cycle
401	  adc->CFGR   = 0; // 12bit
402	  adc->SQR1   = chsel << 6;
403	
404	  /* ADC conversion start.*/
405	  adc->CR |= ADC_CR_ADSTART;
406	  while (adc->CR & ADC_CR_ADSTART)
407	    ;
408	
409	  return adc->DR;
410	}
