580	static void cmd_agc(BaseSequentialStream *chp, int argc, char *argv[])
581	{
582	    const char *cmd;
583	    if (argc == 0) {
584	      chprintf(chp, "usage: agc {cmd} [args...]\r\n");
585	      chprintf(chp, "\tmanual/slow/mid/fast\r\n");
586	      chprintf(chp, "\tenable/disable\r\n");
587	      chprintf(chp, "\tlevel {0-7}\r\n");
588	      chprintf(chp, "\thysteresis {0-3}\r\n");
589	      chprintf(chp, "\tattack {0-31} [scale:0-7]\r\n");
590	      chprintf(chp, "\tdecay {0-31} [scale:0-7]\r\n");
591	      chprintf(chp, "\tmaxgain {0-116}\r\n");
592	      return;
593	    }
594	
595	    cmd = argv[0];
596	    if (strncmp(cmd, "manual", 3) == 0) {
597	      set_agc_mode(AGC_MANUAL);
598	    } else if (strncmp(cmd, "slow", 2) == 0) {
599	      set_agc_mode(AGC_SLOW);
600	    } else if (strncmp(cmd, "mid", 2) == 0) {
601	      set_agc_mode(AGC_MID);
602	    } else if (strncmp(cmd, "fast", 2) == 0) {
603	      set_agc_mode(AGC_FAST);
604	    } else if (strncmp(cmd, "di", 2) == 0) {
605	      tlv320aic3204_agc_config(NULL);
606	    } else if (strncmp(cmd, "enable", 2) == 0) {
607	      tlv320aic3204_agc_config(&config.agc);
608	    } else if (strncmp(cmd, "le", 2) == 0 && argc == 2) {
