            && !button_event_inhibited
			&& ticks >= last_button_down_ticks + BUTTON_DOWN_LONG_TICKS) {
			status |= EVT_BUTTON_DOWN_LONG;
            button_event_inhibited = 1;
		}
	}

    last_button = cur_button;

	return status;
}

